/**
 * Athlete statue portraits (Casey, Nov 16, 2026 — the Diablo
 * treatment): heroic gold statue portraits generated by Nyx from each
 * athlete's avatar photo, bundled as static assets in
 * public/statues/. One master portrait per athlete; the MATERIAL
 * escalates in the Statue component via CSS filters — bronze for a
 * 1-week reign, silver for 2, gold for 3, radiant beyond.
 * Keyed by athleteId with the display name as fallback, mirroring
 * avatars.js (same IDs, verified Nov 15, 2026).
 */
const STATUE_BY_ATHLETE_ID = {
  "jnvRd5FdaXM8PRHGKY8GJJCG9Cs1": "/statues/casey.webp", // Casey Gergely
  "iMPdZlvQjoWVwrPcAvTCsmm2PQC2": "/statues/pat.webp", // Pat Edwards (Patrick Boreskie)
  "MxXK68G3gsUjWiqrM9FYJesIrs52": "/statues/braeden.webp", // Braeden Taylor
  "ey5MXHvO45Ubc4SLEFtsBFjHc1k2": "/statues/graham.webp", // Graham O'Bray
};

const STATUE_BY_NAME = {
  "Casey Gergely": "/statues/casey.webp",
  "Pat Edwards": "/statues/pat.webp",
  "Patrick Boreskie": "/statues/pat.webp",
  "Braeden Taylor": "/statues/braeden.webp",
  "Graham O’Bray": "/statues/graham.webp",
};

/** Bundled statue portrait URL for an athlete, or null. */
export function statueUrlFor(athlete) {
  if (!athlete) return null;
  return (
    STATUE_BY_ATHLETE_ID[athlete.id] ||
    STATUE_BY_NAME[athlete.name] ||
    null
  );
}

export const STATUE_MATERIALS = [
  "Bronze",
  "Silver",
  "Gold",
  "Radiant gold",
  "Eternal radiant",
];

/** Statue material for a reign tier (1..5, clamped). */
export function statueMaterialFor(tier) {
  const t = Math.max(1, Math.min(5, Number(tier) || 1));
  return STATUE_MATERIALS[t - 1];
}
